      "mini_lesson": "- **شیوع سطوح فتق دیسک کمری:** **۹۵٪** فتق‌های دیسک کمری در دو سطح **L4-L5** و **L5-S1** (نقاط حداکثر لوردوز کمری) و ۳ تا ۴٪ در سطح **L3-L4** رخ می‌دهند.\n- **شیوع فتق دیسک در کل جمعیت:** تغییرات دژنراتیو دیسک و ستون فقرات در MRI تا **۷۰٪ افراد بالای ۴۰ سال** بدون علامت دیده می‌شود؛ بنابراین یافته‌های MRI تنها زمانی ارزش جراحی دارند که دقیقاً با علائم ریشه‌ای بیمار در معاینه همخوانی داشته باشند.\n- **میزان موفقیت جراحی دیسککتومی:** در بیمارانی که رادیکولوپاتی واضح منطبق با MRI دارند، جراحی در **بیش از ۹۰٪ موارد** درد رادیکولار تیرکشنده به اندام را تسکین می‌دهد، اما درد محوری کمر یا گردن (Axial pain) تنها در **۶۰ تا ۷۰٪** موارد به طور کامل برطرف می‌شود.\n- **تفاوت تومورهای دم‌اسب با فتق دیسک:** علاوه بر فتق دیسک حجیم مرکزی، تومورهای فضای اپی‌دورال (متاستازها)، هماتوم یا آبسه اپی‌دورال، و تومورهای اینترادورال مثل **اپاندیموم میکسوپاپیلاری (Myxopapillary ependymoma)** که از فیلوم ترمیناله منشأ می‌گیرد، می‌توانند علائم چندریشه‌ای دم‌اسب ایجاد کنند.\n- **تشخیص‌های افتراقی مهم درد کمری و گردنی در لارنس (صفحه ۶۵):**\n- **تشخیص‌های افتراقی بیماری دیسک گردنی (درد گردن یا بازو):** آنژین صدری قلبی (در درد بازوی چپ)، استئوآرتریت و تنگی کانال گردنی، سندرم‌های گیرافتادگی عصب محیطی در اندام فوقانی (مثل تونل کارپال)، تومور یا عفونت ستون فقرات، و بیماری‌های مفصل شانه و آرنج.\n- **تشخیص‌های افتراقی بیماری دیسک کمری (درد کمر یا پا):** لنگش عروقی، فتق (Hernia)، بیماری‌های ژنیکولوژیک، **آنوریسم آئورت شکمی (AAA)**، تومور یا عفونت نخاعی یا رتروپلویک، استئوآرتریت و تنگی کانال کمری، نوروپاتی محیطی و بیماری‌های مفصل هیپ و زانو.",
      "lawrence_lesson": "- **شیوع سطوح فتق دیسک کمری:** **۹۵٪** فتق‌های دیسک کمری در دو سطح **L4-L5** و **L5-S1** (نقاط حداکثر لوردوز کمری) و ۳ تا ۴٪ در سطح **L3-L4** رخ می‌دهند.\n- **شیوع فتق دیسک در کل جمعیت:** تغییرات دژنراتیو دیسک و ستون فقرات در MRI تا **۷۰٪ افراد بالای ۴۰ سال** بدون علامت دیده می‌شود؛ بنابراین یافته‌های MRI تنها زمانی ارزش جراحی دارند که دقیقاً با علائم ریشه‌ای بیمار در معاینه همخوانی داشته باشند.\n- **میزان موفقیت جراحی دیسککتومی:** در بیمارانی که رادیکولوپاتی واضح منطبق با MRI دارند، جراحی در **بیش از ۹۰٪ موارد** درد رادیکولار تیرکشنده به اندام را تسکین می‌دهد، اما درد محوری کمر یا گردن (Axial pain) تنها در **۶۰ تا ۷۰٪** موارد به طور کامل برطرف می‌شود.\n- **تفاوت تومورهای دم‌اسب با فتق دیسک:** علاوه بر فتق دیسک حجیم مرکزی، تومورهای فضای اپی‌دورال (متاستازها)، هماتوم یا آبسه اپی‌دورال، و تومورهای اینترادورال مثل **اپاندیموم میکسوپاپیلاری (Myxopapillary ependymoma)** که از فیلوم ترمیناله منشأ می‌گیرد، می‌توانند علائم چندریشه‌ای دم‌اسب ایجاد کنند.\n- **تشخیص‌های افتراقی مهم درد کمری و گردنی در لارنس (صفحه ۶۵):**\n- **تشخیص‌های افتراقی بیماری دیسک گردنی (درد گردن یا بازو):** آنژین صدری قلبی (در درد بازوی چپ)، استئوآرتریت و تنگی کانال گردنی، سندرم‌های گیرافتادگی عصب محیطی در اندام فوقانی (مثل تونل کارپال)، تومور یا عفونت ستون فقرات، و بیماری‌های مفصل شانه و آرنج.\n- **تشخیص‌های افتراقی بیماری دیسک کمری (درد کمر یا پا):** لنگش عروقی، فتق (Hernia)، بیماری‌های ژنیکولوژیک، **آنوریسم آئورت شکمی (AAA)**، تومور یا عفونت نخاعی یا رتروپلویک، استئوآرتریت و تنگی کانال کمری، نوروپاتی محیطی و بیماری‌های مفصل هیپ و زانو."
