      "mini_lesson": "- **تثبیت اولیه و کلیرانس گردن در لارنس:**\n- تمامی بیماران ترومایی تا زمان کلیرانس رسمی بالینی و رادیولوژیک باید در **کلار گردنی سخت (Hard cervical collar)** و روی تخته بلند پشتی (Long board) فیکس شوند و جابجایی آن‌ها با تکنیک **Log rolling** صورت گیرد.\n- **شرایط خارج کردن کلار گردنی:** ۱) گرافی ساده سری تروما یا CT Scan با برش‌های نازک و بازسازی محوری و کرونال کاملاً نرمال، ۲) معاینه عصبی نرمال، ۳) بیمار هوشیار و بدون درد گردن (یا در صورت تداوم درد گردن با تصویربرداری نرمال، انجام گرافی داینامیک فلکسیون-اکستنشن؛ که اگر به علت اسپاسم عضلانی قابل انجام نباشد، کلار به مدت **۷ تا ۱۰ روز** باقی مانده و پس از رفع اسپاسم مجدداً بررسی می‌شود).\n- **اقدامات حیاتی تثبیت بیمار آسیب نخاعی در لارنس:**\n- دکمپرسیون مثانه با سوند فولی (Self-retaining catheter) جهت جلوگیری از احتباس ادراری و اتونومیک دیس‌رفلکسی.\n- حفظ اکسیژناسیون و فشار خون سیستمیک؛ در صورت بروز **شوک نوروژنیک** (افت ناگهانی تون عروقی سمپاتیک در آسیب‌های T1–T12)، استفاده از وازوپرسورهای سیستمیک مانند **دوپامین** برای حفظ پرفیوژن طناب نخاعی الزامی است.\n- **کی استروئید با دوز بالا در ستون فقرات اندیکاسیون قطعی و اورژانس دارد؟** بر خلاف ترومای نخاعی که مصرف استروئید در آن محل مناقشه است، در **فشار بر نخاع ناشی از تومورهای متاستاتیک اکسترادورال (Metastatic spinal cord compression)**، به محض شک بالینی باید **کورتیکواستروئید وریدی با دوز بالا (دگزامتازون)** به صورت اورژانسی شروع شود تا ادم وازوژنیک کاهش یافته و عملکرد حرکتی حفظ گردد.",
