      "mini_lesson": "- **نمای پاتوگنومونیک تنگی کانال کمری در تصویربرداری (لارنس صفحه ۶۷):**\n  - تنگی کانال از ۳ جهت رخ می‌دهد: از جلو توسط برجستگی دیسک و استئوفیت، و از دو طرف خلفی-جانبی توسط هایپرتروفی مفاصل فاست و لیگامان فلاووم.\n  - در مقطع عرضی (Cross-sectional) در MRI یا CT، ساک دورال به شکل یک **«کلاه سه‌گوش» (Tricornered hat)** دیده می‌شود.\n  - در نمای لترال میلوگرافی، ساک دورال به علت فشارهای متناوب در سطح لامیناها به شکل **«رشته‌ای از سوسیس‌های به هم پیوسته» (String of sausage links)** دیده می‌شود.\n- **درمان جراحی و عارضه آن:** درمان انتخابی در موارد علامت‌دار، دکمپرسیون خلفی با **لامینکتومی چندسطحی (Multilevel decompressive laminectomy)** است. آسیب غیرعمدی به مفاصل فاست بزرگ و دژنره در حین لامینکتومی، در حدود **۱۰٪ موارد** منجر به ناپایداری و نیاز بعدی به **فیوژن کمری (Lumbar fusion)** می‌شود.",
