      "mini_lesson": "- **نکات طلایی شکستگی‌های C1 و C2 در لارنس (صفحه ۵۹):**\n  - **شکستگی جفرسون (C1):** در **۴۰٪ موارد با شکستگی مهره C2 همراه است**. به دلیل گشاد بودن کانال نخاعی در این سطح، **به‌ندرت** با آسیب عصبی مراجعه می‌کند. نماهای تشخیصی: گرافی Open-mouth و CT Scan آگزیال.\n  - **شکستگی زائده دندانی C2 (Odontoid fracture):**\n    - **تیپ I (نوک دنس)** و **تیپ III (امتداد به تنه C2):** خون‌رسانی خوبی دارند و با **Halo vest به مدت ۳ تا ۶ ماه** به خوبی جوش می‌خورند.\n    - **تیپ II (قاعده دنس):** به دلیل خون‌رسانی ضعیف، ریسک بالای جوش نخوردن (Nonunion) دارد. در بیماران **زیر ۴۰ سال، غیرسیگاری و با جابجایی کمتر از 4 mm** با Halo vest بهبود می‌یابد؛ اما در **سن بالای ۴۰ سال، سیگاری‌ها یا جابجایی ≥4 mm** کاندید جراحی (پیچ قدامی ادونتوئید در صورت سالم بودن لیگامان عرضی، یا فیوژن خلفی C1-C2) است.\n  - **شکستگی جلاد C2 (Hangman fracture):** شکستگی دوطرفه پدیکول C2 در اثر هایپراکستنشن حاد؛ **۹۵٪ بیماران از نظر عصبی کاملاً سالم هستند** و اکثریت با **Halo vest به مدت ۳ تا ۶ ماه** درمان می‌شوند.",
