      "rationale": "طبق فصل ۲۸ لارنس (صفحه ۲۵، مبحث Brain Attack and Cerebrovascular Disease)، **بیماری‌های عروقی مغزی (Cerebrovascular events / Stroke)** شایع‌ترین علت بروز نقص عصبی کانونی **حاد و ناگهانی (Sudden ictus)** در غیاب تروما هستند.\n- واژه **Stroke** به معنای «ضربه ناگهانی» (Sudden ictus) است و به دو دسته کلی تقسیم می‌شود:\n  1. **انفارکتوس ایسکمیک (Ischemic infarction):** حدود ۸۰ تا ۸۵٪ کل سکته‌ها (شامل TIA و RIND و سکته کامل که در آن سکته آمبولیک به مراتب شایع‌تر از ترومبوتیک/لاکونار است).\n  2. **خونریزی داخل مغزی (Intracerebral hemorrhage - ICH):** حدود ۱۵ تا ۲۰٪ کل سکته‌ها (شامل خونریزی داخل پارانشیمی خودبه‌خودی یا IPH و خونریزی ساب‌آراکنوئید یا SAH).\n\n> 💡 **نکته تکمیلی و تطبیقی آزمون‌ها:** این سوال تکرار دقیق سوال قبل با جابجایی گزینه‌هاست. **بیماری‌های عروقی مغزی (Stroke)** شایع‌ترین علت نقص نورولوژیک حاد و غیرتروماتیک هستند (گزینه C).",
