      "mini_lesson": "- **تعاریف زمانی حوادث ایسکمیک مغزی در لارنس (صفحات ۲۵ و ۲۶):**\n- **TIA (حمله ایسکمیک گذرا):** نقص عصبی ایسکمیک کاملاً برگشت‌پذیر که **کمتر از ۲۴ ساعت** طول می‌کشد (در عمل **۷۰٪ موارد TIA کمتر از ۱۰ دقیقه** طول می‌کشند).\n- **RIND (نقص عصبی ایسکمیک برگشت‌پذیر):** نقص عصبی کانونی گذرا که **بیش از ۱ روز (۲۴ ساعت) اما کمتر از ۱ هفته** طول می‌کشد و سپس کاملاً برطرف می‌شود.\n- **Completed Ischemic Infarction:** نقص عصبی دائمی ناشی از مرگ بافت مغز.\n- **مقایسه ریسک‌فاکتورها در لارنس (صفحه ۲۶):**\n- **ریسک‌فاکتورهای آترواسکلروز مغزی (ایسکمی):** سابقه خانوادگی، پرفشاری خون، سیگار، دیابت ملیتوس و هیپرلیپیدمی.\n- **ریسک‌فاکتورهای خونریزی داخل پارانشیمی (IPH):** پرفشاری خون، سوءمصرف مواد (به‌ویژه **کوکائین و مت‌آمفتامین**)، دمانس (آنژیوپاتی آمیلوئید) و کواگولوپاتی.\n- **ریسک‌فاکتورهای SAH آنوریسمال:** سابقه خانوادگی و سابقه قبلی آنوریسم Berry.\n- **افتراق بالینی سکته ایسکمیک از خونریزی مغزی (ICH) در لارنس (صفحه ۲۶):** برخلاف بیماران دچار ICH که معمولاً با سردرد ناگهانی شدید، تهوع، استفراغ و افت سطح هوشیاری مراجعه می‌کنند، بیماران دچار **انفارکتوس ایسکمیک** معمولاً با شروع سریع نقص عصبی کانونی **بدون سردرد (یا با سردرد بسیار خفیف)** و **بدون تغییر در سطح هوشیاری** مراجعه می‌نمایند.",
