      "mini_lesson": "- **راهنمای تشخیص سریع انواع خونریزی‌های داخل جمجمه در CT Scan بر اساس لارنس (صفحات ۱۴ تا ۲۴):**\n  1. **هماتوم اپی‌دورال (EDH):** سفید، **عدسی‌شکل (Biconvex / Lenticular)**، محدود به خطوط سوتور، اغلب مجاور شکستگی استخوان تمپورال (پارگی شریان MMA).\n  2. **هماتوم ساب‌دورال حاد (Acute SDH):** سفید، **هلالی‌شکل (Crescentic / Rind of a watermelon)**، عبورکننده از خطوط سوتور، محدود به فالکس و تنتوریوم (پارگی وریدهای پل‌زننده یا پارگی کورتکس).\n  3. **خونریزی ساب‌آراکنوئید (SAH):** سفیدی منتشر در داخل شیارهای قشر مغز (Sulci) و سیسترن‌های قاعده‌ای (Basal cisterns).\n  4. **هماتوم داخل پارانشیمی (IPH):** توده سفید گرد یا بیضی در داخل بافت مغز (در فشار خون بالا در پوتامن/تالاموس؛ در آنژیوپاتی آمیلوئید در لوب پاریتو-اکسیپیتال؛ در تروما در لوب فرونتال و تمپورال).",
